"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["36870"],{58665(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.dia_nao_util_congelado.data_ausente","status":422,"titulo":"A data do dia n\xe3o \xfatil congelado n\xe3o pode ser o valor default"},"descricao":{"codigo":"uniplus.selecao.dia_nao_util_congelado.data_ausente","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["Um dia n\xe3o \xfatil do calend\xe1rio de dias \xfateis vigente traz a data 0001-01-01, que \xe9 como uma data\\nomitida se materializa. Congelar esse valor numa vers\xe3o publicada a tornaria imposs\xedvel de reler\\ndepois, e com ela morreriam a restaura\xe7\xe3o e a retifica\xe7\xe3o do certame.","O calend\xe1rio de dias \xfateis vigente \xe9 cadastrado no m\xf3dulo Configura\xe7\xe3o, e a vers\xe3o do processo\\ncongela uma c\xf3pia dele por valor, com a lista dos dias n\xe3o \xfateis (UNI-REQ-0080). Ao copi\xe1-lo, o\\nsistema confere de novo cada dia e o conjunto, e recusa o que o cadastro n\xe3o aceitaria. A recusa\\ns\xf3 vale para o processo que depende do calend\xe1rio, isto \xe9, o que tem prazo de recurso (ver\\n[calend\xe1rio vigente ausente](/erros/uniplus.selecao.processo_seletivo.calendario_vigente_ausente)); um processo sem contagem sobre dia \xfatil segue normalmente, porque n\xe3o usa o dado.","A confer\xeancia vem depois das da localidade ([`localidade_ausente`](/erros/uniplus.selecao.processo_seletivo.localidade_ausente)) e da conven\xe7\xe3o de contagem\\n([`algoritmo_contagem_prazo_nao_declarado`](/erros/uniplus.selecao.processo_seletivo.algoritmo_contagem_prazo_nao_declarado)), e antes das demais confer\xeancias de conformidade e do cronograma. A consulta de\\nconformidade do processo mostra o item \\"Calend\xe1rio de dias \xfateis vigente\\" como pendente enquanto o\\ncalend\xe1rio vigente estiver nessa condi\xe7\xe3o. Nada \xe9 gravado.","Os dias s\xe3o conferidos um a um, na ordem em que o calend\xe1rio os lista, e o primeiro dia com\\ndefeito interrompe a c\xf3pia. As confer\xeancias do calend\xe1rio como um todo (identificador, vers\xe3o,\\nlista vazia e dia repetido) v\xeam depois das de todos os dias. Dentro de um dia, vem primeiro a confer\xeancia da forma bruta ([`forma_territorial_invalida`](/erros/uniplus.selecao.calendario_vigente.forma_territorial_invalida)), depois a data, a\\nabrang\xeancia e o recorte territorial."],"comoResolver":["A causa n\xe3o est\xe1 na configura\xe7\xe3o do processo, e nada nela corrige a recusa: o dado vem do\\ncalend\xe1rio de dias \xfateis vigente, cadastrado no m\xf3dulo Configura\xe7\xe3o. Como a vers\xe3o publicada\\ncongela o calend\xe1rio por valor, a corre\xe7\xe3o \xe9 na origem, antes de publicar ou retificar:\\ncadastre um calend\xe1rio corrigido, que o cadastro confere ao criar, coloque-o em vig\xeancia\\ne repita a opera\xe7\xe3o.","O cadastro recusa o dia sem data ao criar o calend\xe1rio. Um calend\xe1rio vigente nessa condi\xe7\xe3o\\nindica dado gravado por caminho que n\xe3o passou por essa confer\xeancia, e a causa \xe9 investigada\\npela equipe t\xe9cnica do Uni+."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Dia nao util congelado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);